import { useEffect, useMemo, useState } from 'react';
import { Activity, BarChart3, Bot, Database, ExternalLink, FileText, FolderTree, History, LayoutList, Loader2, MessageSquareText, Pencil, Plus, RefreshCw, Save, Search, Send, ShieldCheck, Trash2, Upload, Workflow, X } from 'lucide-react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { useAuth } from '@/hooks/useAuth';
import { useToast } from '@/hooks/use-toast';
import { formatTelegramAdminError, telegramAdminRequest } from '@/lib/telegramAdminApi';
import { AdminTelegramReferrals } from './AdminTelegramReferrals';

type AccessMode = 'free' | 'premium' | 'referral' | 'hasad';
type ManagedMenuItem = { id: number; label: string; actionType: 'url' | 'message' | 'file'; actionValue: string; rowIndex: number; sortOrder: number; enabled: boolean; accessMode: AccessMode; createdAt: string; updatedAt: string };
type ManagedSection = { sectionKey: string; displayLabel: string; enabled: boolean; accessMode: AccessMode | 'subscription'; sortOrder: number };
type AuditLog = { id: number; action: string; entityType: string; entityId: string | null; createdAt: string };
type ManagedMessageTemplate = { messageKey: 'welcome' | 'about' | 'help'; title: string; content: string };
type ManagedSource = { id: number; title: string; description: string; collection: string; sortOrder: number; isFeatured: boolean; updatedAt: string };
type ManagedFolder = { id: number; name: string; collection: string; sortOrder: number; driveFolderId: string; parentDriveFolderId: string | null };
type ManagedBroadcast = { id: number; message: string | null; status: 'draft' | 'sending' | 'sent' | 'cancelled'; recipientCount: number; successCount: number; failureCount: number; scheduledFor: string | null; createdAt: string; completedAt: string | null };
type SubscriptionRequest = { id: number; telegramUserId: string; telegramUsername: string | null; telegramFirstName: string | null; telegramLastName: string | null; paymentMethod: string | null; createdAt: string };
type UsageAnalytics = { periodDays: number; totalEvents: number; uniqueUsers: number; eventTypes: Array<{ eventType: string; count: number }>; topSections: Array<{ sectionKey: string; count: number }>; topSources: Array<{ sourceId: number; title: string; count: number }> };
type VisitPeriod = 'day' | 'week' | 'month';
type VisitAnalytics = { period: VisitPeriod; since: string; platformVisits: { total: number; uniqueUsers: number }; hasadVisits: { total: number; uniqueUsers: number }; users: Array<{ telegramUserId: string; telegramUsername: string | null; telegramFirstName: string | null; telegramLastName: string | null; platformVisitedAt: string | null; hasadVisitedAt: string | null }> };
type BotStats = { totalSubscribers: number; activeUsers: number; activeUsersPeriodDays: number; lastActiveAt: string | null; storageMode?: 'supabase' | 'legacy'; usage?: { totalEvents: number; totalSupportRequests: number; topQueries: Array<{ query: string; count: number }> }; platformVisits?: { total: number }; hasadVisits?: { total: number } };
type UploadDraft = { title: string; description: string; collection: string; category: string; sortOrder: number; isFeatured: boolean };
const emptyUploadDraft: UploadDraft = { title: '', description: '', collection: 'judicial', category: 'general', sortOrder: 0, isFeatured: false };
type Draft = Omit<ManagedMenuItem, 'id' | 'createdAt' | 'updatedAt' | 'accessMode'> & { accessMode?: ManagedMenuItem['accessMode'] };
const emptyDraft: Draft = { label: '', actionType: 'url', actionValue: '', rowIndex: 100, sortOrder: 0, enabled: true, accessMode: 'free' };
const accessModeLabel = (mode: AccessMode | 'subscription') => mode === 'free' ? 'متاح مجانًا' : mode === 'hasad' ? 'يتطلب زيارة حصاد اليوم' : mode === 'referral' ? 'إحالة فقط' : 'مدفوع';
const accessModeDescription = () => 'لا يغيّر هذا الاختيار اشتراكات أو طلبات سابقة، وتبقى شروط القنوات وزيارة منصة الناصر الأساسية فعّالة.';
const restrictedAccessLabel = (_sectionKey?: string) => 'اختر بين مجاني أو مدفوع أو إحالة أو زيارة حصاد اليوم';

const uploadContentTypesByExtension: Record<string, string> = {
  pdf: 'application/pdf', doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', txt: 'text/plain',
};

function resolveUploadContentType(file: File): string | undefined {
  const browserType = file.type.split(';', 1)[0]?.trim().toLowerCase();
  if (browserType && browserType !== 'application/octet-stream') return browserType;
  const extension = file.name.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1];
  return extension ? uploadContentTypesByExtension[extension] : undefined;
}

function adminApiErrorMessage(error: unknown): string | undefined {
  const messages: Record<string, string> = {
    file_name_required: 'لم يُقرأ اسم الملف. اختر الملف مرة أخرى وحاول مجددًا.',
    file_content_required: 'لم تُقرأ محتويات الملف. اختر الملف مرة أخرى وحاول مجددًا.',
    unsupported_file_type: 'نوع الملف غير مدعوم. الأنواع المقبولة: PDF وWord وExcel وTXT.',
    empty_file: 'الملف المحدد فارغ. اختر ملفًا يحتوي بيانات.',
    file_too_large: 'حجم الملف أكبر من الحد المسموح به للرفع.',
    invalid_source_fields: 'أكمل اسم العرض والوصف واختر قسمًا وتصنيفًا صالحين.',
    storage_upload_failed: 'تعذر حفظ الملف في تخزين البوت مؤقتًا. حاول لاحقًا.',
    drive_library_read_only: 'الرفع المحلي غير متاح في تشغيل Supabase. عدّل بيانات ملف Drive من قسم الفهرس فقط.',
    subscription_processing_failed: 'تعذر إتمام القرار الذري للاشتراك. لم يُرسل إشعار للمستخدم؛ أعد تحميل الطلب وحاول مرة أخرى.',
    access_grant_failed: 'تعذر منح الوصول بعد الاعتماد. لم يُعتبر القرار مكتملًا؛ أعد المحاولة بعد التحقق من بيانات الطلب.',
    schedule_unavailable_supabase: 'الجدولة التلقائية غير مفعّلة في تشغيل Supabase حاليًا؛ استخدم الإرسال الفوري بعد تأكيد SEND.',
  };
  return typeof error === 'string' ? messages[error] : undefined;
}

function actionLabel(type: ManagedMenuItem['actionType']) { return type === 'url' ? 'فتح رابط' : type === 'file' ? 'إرسال ملف' : 'عرض رسالة'; }
function visitorDisplayName(visitor: VisitAnalytics['users'][number]) { return [visitor.telegramFirstName, visitor.telegramLastName].filter(Boolean).join(' ') || (visitor.telegramUsername ? `@${visitor.telegramUsername}` : `مستخدم ${visitor.telegramUserId}`); }

export default function AdminTelegramBot() {
  const { session, role } = useAuth();
  const { toast } = useToast();
  const [items, setItems] = useState<ManagedMenuItem[]>([]);
  const [sections, setSections] = useState<ManagedSection[]>([]);
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [templates, setTemplates] = useState<ManagedMessageTemplate[]>([]);
  const [sources, setSources] = useState<ManagedSource[]>([]);
  const [sourceQuery, setSourceQuery] = useState('');
  const [sourceTotal, setSourceTotal] = useState(0);
  const [folders, setFolders] = useState<ManagedFolder[]>([]);
  const [folderQuery, setFolderQuery] = useState('');
  const [broadcasts, setBroadcasts] = useState<ManagedBroadcast[]>([]);
  const [broadcastMessage, setBroadcastMessage] = useState('');
  const [scheduleFor, setScheduleFor] = useState('');
  const [schedulingBroadcastId, setSchedulingBroadcastId] = useState<number | null>(null);
  const [scheduleConfirmation, setScheduleConfirmation] = useState('');
  const [subscriptionRequests, setSubscriptionRequests] = useState<SubscriptionRequest[]>([]);
  const [usageAnalytics, setUsageAnalytics] = useState<UsageAnalytics | null>(null);
  const [visitAnalytics, setVisitAnalytics] = useState<VisitAnalytics | null>(null);
  const [botStats, setBotStats] = useState<BotStats | null>(null);
  const [lastSyncedAt, setLastSyncedAt] = useState<string | null>(null);
  const [visitPeriod, setVisitPeriod] = useState<VisitPeriod>('month');
  const [visitLoading, setVisitLoading] = useState(false);
  const [uploadDraft, setUploadDraft] = useState<UploadDraft>(emptyUploadDraft);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [menuItemFile, setMenuItemFile] = useState<File | null>(null);
  const [draft, setDraft] = useState<Draft>(emptyDraft);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [savingMenuItemAccessId, setSavingMenuItemAccessId] = useState<number | null>(null);
  const [savingSection, setSavingSection] = useState<string | null>(null);
  const [savingTemplate, setSavingTemplate] = useState<string | null>(null);
  const [sourceLoading, setSourceLoading] = useState(false);
  const [savingSource, setSavingSource] = useState<number | null>(null);
  const [uploading, setUploading] = useState(false);
  const [foldersLoading, setFoldersLoading] = useState(false);
  const [savingFolder, setSavingFolder] = useState<number | null>(null);
  const [broadcastSaving, setBroadcastSaving] = useState(false);
  const [confirmingBroadcastId, setConfirmingBroadcastId] = useState<number | null>(null);
  const [broadcastConfirmation, setBroadcastConfirmation] = useState('');
  const [subscriptionActionId, setSubscriptionActionId] = useState<number | null>(null);

  const request = <T extends Record<string, any> = Record<string, any>>(path: string, options: RequestInit = {}) => telegramAdminRequest<T>(session?.access_token, path, options);

  const load = async () => {
    if (!session?.access_token || role !== 'admin') return;
    setLoading(true);
    const requests = [
      ['menu', () => request('/api/telegram/admin/menu-items')],
      ['sections', () => request('/api/telegram/admin/sections')],
      ['logs', () => request('/api/telegram/admin/audit-logs')],
      ['templates', () => request('/api/telegram/admin/message-templates')],
      ['broadcasts', () => request('/api/telegram/admin/broadcasts')],
      ['subscriptions', () => request('/api/telegram/admin/subscriptions/pending')],
      ['usage', () => request('/api/telegram/admin/usage-analytics?days=30')],
      ['visits', () => request(`/api/telegram/admin/visit-analytics?period=${visitPeriod}`)],
      ['stats', () => request('/api/telegram/admin-stats')],
    ] as const;
    const results = await Promise.allSettled(requests.map(([, loader]) => loader()));
    const failed: string[] = [];
    results.forEach((result, index) => {
      const key = requests[index]?.[0];
      if (result.status === 'rejected') { failed.push(`${key}: ${formatTelegramAdminError(result.reason)}`); return; }
      const body = result.value as any;
      if (key === 'menu') setItems(body.items ?? []);
      if (key === 'sections') setSections(body.sections ?? []);
      if (key === 'logs') setLogs(body.logs ?? []);
      if (key === 'templates') setTemplates(body.templates ?? []);
      if (key === 'broadcasts') setBroadcasts(body.broadcasts ?? []);
      if (key === 'subscriptions') setSubscriptionRequests(body.requests ?? []);
      if (key === 'usage') setUsageAnalytics(body.analytics ?? null);
      if (key === 'visits') setVisitAnalytics(body.analytics ?? null);
      if (key === 'stats') setBotStats(body);
      setLastSyncedAt(new Date().toISOString());
    });
    if (failed.length) toast({ title: 'اكتمل التحميل مع وجود أقسام تحتاج مراجعة', description: failed.join(' | '), variant: 'destructive' });
    setLoading(false);
  };

  useEffect(() => { void load(); }, [session?.access_token, role]);
  useEffect(() => {
    if (editingId === null) return;
    const frame = window.requestAnimationFrame(() => document.querySelector<HTMLElement>('aside.h-fit')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
    return () => window.cancelAnimationFrame(frame);
  }, [editingId]);
  const loadVisitAnalytics = async (period: VisitPeriod) => {
    setVisitPeriod(period); setVisitLoading(true);
    try { const result = await request(`/api/telegram/admin/visit-analytics?period=${period}`); setVisitAnalytics(result.analytics ?? null); }
    catch (error) { toast({ title: 'تعذر تحميل إحصاءات الزيارات', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setVisitLoading(false); }
  };
  const title = useMemo(() => editingId ? 'تعديل زر البوت' : 'إضافة زر جديد', [editingId]);
  const activeDraftAccessMode = draft.accessMode ?? items.find(item => item.id === editingId)?.accessMode ?? 'free';
  const reset = () => { setDraft(emptyDraft); setEditingId(null); setMenuItemFile(null); };

  const save = async () => {
    if (!draft.label.trim() || (draft.actionType === 'file' ? !menuItemFile && !draft.actionValue.trim() : !draft.actionValue.trim())) { toast({ title: 'أكمل البيانات المطلوبة', description: draft.actionType === 'file' ? 'اسم الزر والملف مطلوبان.' : 'اسم الزر والمحتوى أو الرابط مطلوبان.', variant: 'destructive' }); return; }
    setSaving(true);
    try {
      if (draft.actionType === 'file' && menuItemFile) {
        const contentBase64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error('تعذر قراءة الملف')); reader.onload = () => resolve(String(reader.result).split(',')[1] ?? ''); reader.readAsDataURL(menuItemFile); });
        await request(editingId ? `/api/telegram/admin/menu-items/${editingId}/upload` : '/api/telegram/admin/menu-items/upload', { method: editingId ? 'PUT' : 'POST', body: JSON.stringify({ ...draft, actionType: 'file', accessMode: activeDraftAccessMode, fileName: menuItemFile.name, contentType: menuItemFile.type, contentBase64 }) });
      } else {
        await request(editingId ? `/api/telegram/admin/menu-items/${editingId}` : '/api/telegram/admin/menu-items', { method: editingId ? 'PUT' : 'POST', body: JSON.stringify({ ...draft, accessMode: activeDraftAccessMode }) });
      }
      toast({ title: editingId ? 'تم تحديث الزر' : 'تمت إضافة الزر', description: 'سينعكس التعديل عند فتح المستخدم القائمة الرئيسية في البوت.' });
      reset(); await load();
    } catch (error) { toast({ title: 'تعذر حفظ الزر', description: formatTelegramAdminError(error), variant: 'destructive' }); }
    finally { setSaving(false); }
  };

  const updateMenuItemAccessMode = async (item: ManagedMenuItem, accessMode: ManagedMenuItem['accessMode']) => {
    if (item.accessMode === accessMode) return;
    setSavingMenuItemAccessId(item.id);
    try {
      const result = await request(`/api/telegram/admin/menu-items/${item.id}`, { method: 'PUT', body: JSON.stringify({ ...item, accessMode }) });
      setItems(current => current.map(currentItem => currentItem.id === item.id ? (result.item ?? { ...currentItem, accessMode }) : currentItem));
      toast({ title: 'تم تحديث نمط الوصول', description: accessMode === 'free' ? `أصبح «${item.label}» متاحًا مجانًا.` : `أصبح «${item.label}» مدفوعًا أو متاحًا بالإحالة.` });
    } catch (error) {
      toast({ title: 'تعذر تحديث نمط الوصول', description: error instanceof Error ? error.message : undefined, variant: 'destructive' });
    } finally { setSavingMenuItemAccessId(null); }
  };

  const remove = async (id: number) => {
    if (!window.confirm('هل تريد حذف هذا الزر من البوت؟')) return;
    try { await request(`/api/telegram/admin/menu-items/${id}`, { method: 'DELETE' }); toast({ title: 'تم حذف الزر' }); await load(); }
    catch (error) { toast({ title: 'تعذر حذف الزر', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
  };

  const updateSectionState = (sectionKey: string, patch: Partial<ManagedSection>) => setSections(current => current.map(section => section.sectionKey === sectionKey ? { ...section, ...patch } : section));
  const saveSection = async (section: ManagedSection) => {
    setSavingSection(section.sectionKey);
    try {
      const result = await request(`/api/telegram/admin/sections/${section.sectionKey}`, { method: 'PUT', body: JSON.stringify(section) });
      setSections(current => current.map(value => value.sectionKey === section.sectionKey ? result.section : value));
      toast({ title: 'تم تحديث القسم', description: 'سيظهر التعديل عند فتح المستخدم القائمة الرئيسية لاحقًا.' });
    } catch (error) { toast({ title: 'تعذر حفظ إعداد القسم', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSavingSection(null); }
  };

  const updateTemplateState = (messageKey: ManagedMessageTemplate['messageKey'], content: string) => setTemplates(current => current.map(template => template.messageKey === messageKey ? { ...template, content } : template));
  const saveTemplate = async (template: ManagedMessageTemplate) => {
    if (!template.content.trim()) { toast({ title: 'نص الرسالة مطلوب', variant: 'destructive' }); return; }
    setSavingTemplate(template.messageKey);
    try {
      const result = await request(`/api/telegram/admin/message-templates/${template.messageKey}`, { method: 'PUT', body: JSON.stringify({ content: template.content }) });
      setTemplates(current => current.map(value => value.messageKey === template.messageKey ? result.template : value));
      toast({ title: 'تم حفظ قالب الرسالة', description: 'سيظهر النص الجديد للمستخدمين عند التدفق المرتبط به.' });
    } catch (error) { toast({ title: 'تعذر حفظ قالب الرسالة', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSavingTemplate(null); }
  };

  const loadSources = async () => {
    setSourceLoading(true);
    try {
      const result = await request(`/api/telegram/admin/sources?q=${encodeURIComponent(sourceQuery)}&page=1`);
      setSources(result.sources ?? []); setSourceTotal(result.total ?? 0);
    } catch (error) { toast({ title: 'تعذر تحميل ملفات البوت', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSourceLoading(false); }
  };
  const updateSourceState = (id: number, patch: Partial<ManagedSource>) => setSources(current => current.map(source => source.id === id ? { ...source, ...patch } : source));
  const saveSource = async (source: ManagedSource) => {
    setSavingSource(source.id);
    try {
      const result = await request(`/api/telegram/admin/sources/${source.id}`, { method: 'PUT', body: JSON.stringify({ title: source.title, description: source.description, sortOrder: source.sortOrder, isFeatured: source.isFeatured }) });
      setSources(current => current.map(value => value.id === source.id ? result.source : value));
      toast({ title: 'تم تحديث بيانات الملف' });
    } catch (error) { toast({ title: 'تعذر تحديث الملف', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSavingSource(null); }
  };
  const removeSource = async (source: ManagedSource) => {
    if (!window.confirm(`سيُحذف «${source.title}» من فهرس البوت فقط، ولن يُحذف من Google Drive. هل تريد المتابعة؟`)) return;
    try { await request(`/api/telegram/admin/sources/${source.id}`, { method: 'DELETE' }); setSources(current => current.filter(value => value.id !== source.id)); setSourceTotal(total => Math.max(0, total - 1)); toast({ title: 'تم حذف الملف من فهرس البوت فقط' }); }
    catch (error) { toast({ title: 'تعذر حذف الملف', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
  };
  const uploadSource = async () => {
    if (!uploadFile || !uploadDraft.title.trim() || !uploadDraft.description.trim()) { toast({ title: 'أكمل بيانات الملف', description: 'اختر ملفًا واكتب اسم العرض والوصف.', variant: 'destructive' }); return; }
    if (uploadFile.size > 20 * 1024 * 1024) { toast({ title: 'حجم الملف كبير', description: 'الحد الإداري للرفع 20 ميغابايت لضمان التسليم الآمن داخل تيليغرام.', variant: 'destructive' }); return; }
    const contentType = resolveUploadContentType(uploadFile);
    if (!contentType) { toast({ title: 'نوع الملف غير مدعوم', description: 'ارفع ملف PDF أو Word أو Excel أو TXT فقط.', variant: 'destructive' }); return; }
    setUploading(true);
    try {
      const contentBase64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error('تعذر قراءة الملف')); reader.onload = () => resolve(String(reader.result).split(',')[1] ?? ''); reader.readAsDataURL(uploadFile); });
      await request('/api/telegram/admin/sources/upload', { method: 'POST', body: JSON.stringify({ ...uploadDraft, fileName: uploadFile.name, contentType, contentBase64 }) });
      toast({ title: 'تم رفع الملف وإضافته إلى فهرس البوت', description: 'سيُرسل للمستخدمين كمستند داخل تيليغرام من دون عرض رابط التخزين.' });
      setUploadFile(null); setUploadDraft(emptyUploadDraft); await loadSources();
    } catch (error) { toast({ title: 'تعذر رفع الملف', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setUploading(false); }
  };
  const loadFolders = async () => {
    setFoldersLoading(true);
    try { const result = await request(`/api/telegram/admin/folders?q=${encodeURIComponent(folderQuery)}`); setFolders(result.folders ?? []); }
    catch (error) { toast({ title: 'تعذر تحميل المجلدات', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setFoldersLoading(false); }
  };
  const updateFolderState = (id: number, patch: Partial<ManagedFolder>) => setFolders(current => current.map(folder => folder.id === id ? { ...folder, ...patch } : folder));
  const saveFolder = async (folder: ManagedFolder) => {
    setSavingFolder(folder.id);
    try { const result = await request(`/api/telegram/admin/folders/${folder.id}`, { method: 'PUT', body: JSON.stringify({ name: folder.name, sortOrder: folder.sortOrder }) }); setFolders(current => current.map(value => value.id === folder.id ? result.folder : value)); toast({ title: 'تم تحديث المجلد' }); }
    catch (error) { toast({ title: 'تعذر تحديث المجلد', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSavingFolder(null); }
  };
  const removeFolder = async (folder: ManagedFolder) => {
    if (!window.confirm(`لا يمكن حذف المجلد إلا إذا كان فارغًا. هل تريد محاولة حذف «${folder.name}»؟`)) return;
    try { await request(`/api/telegram/admin/folders/${folder.id}`, { method: 'DELETE' }); setFolders(current => current.filter(value => value.id !== folder.id)); toast({ title: 'تم حذف المجلد الفارغ' }); }
    catch (error) { toast({ title: 'تعذر حذف المجلد', description: error instanceof Error && error.message.includes('folder_not_empty') ? 'المجلد يحتوي ملفات أو مجلدات فرعية؛ احذف أو انقل محتواه أولاً.' : 'تحقق من أن المجلد فارغ ثم أعد المحاولة.', variant: 'destructive' }); }
  };
  const createBroadcast = async () => {
    if (!broadcastMessage.trim()) { toast({ title: 'اكتب رسالة البث أولًا', variant: 'destructive' }); return; }
    setBroadcastSaving(true);
    try { const result = await request('/api/telegram/admin/broadcasts', { method: 'POST', body: JSON.stringify({ message: broadcastMessage }) }); setBroadcasts(current => [result.broadcast, ...current]); setBroadcastMessage(''); toast({ title: 'تم إنشاء مسودة البث', description: 'راجِع النص وعدد المستلمين ثم أكّد الإرسال بكتابة SEND.' }); }
    catch (error) { toast({ title: 'تعذر إنشاء مسودة البث', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setBroadcastSaving(false); }
  };
  const cancelBroadcast = async (id: number) => {
    try { await request(`/api/telegram/admin/broadcasts/${id}/cancel`, { method: 'POST' }); setBroadcasts(current => current.map(item => item.id === id ? { ...item, status: 'cancelled' } : item)); toast({ title: 'تم إلغاء مسودة البث' }); }
    catch (error) { toast({ title: 'تعذر إلغاء المسودة', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
  };
  const confirmBroadcast = async (id: number) => {
    if (broadcastConfirmation !== 'SEND') { toast({ title: 'أدخل SEND لتأكيد الإرسال', variant: 'destructive' }); return; }
    setBroadcastSaving(true);
    try { const result = await request(`/api/telegram/admin/broadcasts/${id}/confirm`, { method: 'POST', body: JSON.stringify({ confirmation: 'SEND' }) }); setBroadcasts(current => current.map(item => item.id === id ? { ...item, status: 'sent', successCount: result.successCount, failureCount: result.failureCount, completedAt: new Date().toISOString() } : item)); setConfirmingBroadcastId(null); setBroadcastConfirmation(''); toast({ title: 'اكتمل البث', description: `نجح الإرسال: ${result.successCount}، تعذر: ${result.failureCount}.` }); }
    catch (error) { toast({ title: 'تعذر تنفيذ البث', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setBroadcastSaving(false); }
  };
  const scheduleBroadcast = async (id: number) => {
    if (!scheduleFor) { toast({ title: 'اختر تاريخ ووقت الإرسال', variant: 'destructive' }); return; }
    if (scheduleConfirmation !== 'SCHEDULE') { toast({ title: 'أدخل SCHEDULE لتأكيد الجدولة', variant: 'destructive' }); return; }
    const scheduledFor = new Date(scheduleFor);
    if (Number.isNaN(scheduledFor.getTime()) || scheduledFor.getTime() < Date.now() + 60_000) { toast({ title: 'اختر موعدًا بعد دقيقة واحدة على الأقل', variant: 'destructive' }); return; }
    setBroadcastSaving(true);
    try { const result = await request(`/api/telegram/admin/broadcasts/${id}/schedule`, { method: 'POST', body: JSON.stringify({ confirmation: 'SCHEDULE', scheduledFor: scheduledFor.toISOString() }) }); setBroadcasts(current => current.map(item => item.id === id ? { ...item, scheduledFor: result.scheduledFor } : item)); setSchedulingBroadcastId(null); setScheduleFor(''); setScheduleConfirmation(''); toast({ title: 'تمت جدولة البث', description: `سيُرسل تلقائيًا في ${scheduledFor.toLocaleString('ar-YE')}.` }); }
    catch (error) { toast({ title: 'تعذرت جدولة البث', description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setBroadcastSaving(false); }
  };
  const decideSubscription = async (subscriptionRequest: SubscriptionRequest, decision: 'approve' | 'reject') => {
    const label = decision === 'approve' ? 'اعتماد' : 'رفض';
    if (!window.confirm(`هل تؤكد ${label} طلب الاشتراك رقم #${subscriptionRequest.id}؟ سيُرسل إشعار تلقائي للمستخدم.`)) return;
    setSubscriptionActionId(subscriptionRequest.id);
    try { const result = await request(`/api/telegram/admin/subscriptions/${subscriptionRequest.id}/${decision}`, { method: 'POST' }); setSubscriptionRequests(current => current.filter(item => item.id !== subscriptionRequest.id)); toast({ title: `تم ${label} الطلب`, description: result.notified ? 'أُرسل إشعار تلقائي للمستخدم.' : 'تم حفظ القرار، وتعذر إشعار المستخدم حاليًا.' }); }
    catch (error) { toast({ title: `تعذر ${label} الطلب`, description: error instanceof Error ? error.message : undefined, variant: 'destructive' }); }
    finally { setSubscriptionActionId(null); }
  };

  return <AdminLayout><div className="space-y-6 bg-slate-50/40 pb-10" dir="rtl">
    <section className="overflow-hidden rounded-[2rem] bg-gradient-to-l from-slate-950 via-indigo-950 to-blue-900 p-6 text-white shadow-2xl shadow-indigo-950/10 md:p-8">
      <div className="flex flex-col gap-6 xl:flex-row xl:items-center xl:justify-between"><div className="flex items-start gap-4"><div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-white/10 ring-1 ring-white/15"><Bot className="h-7 w-7 text-sky-200" /></div><div><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-black tracking-tight md:text-3xl">مركز تشغيل بوت الناصر</h1><span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-400/15 px-2.5 py-1 text-[11px] font-bold text-emerald-200 ring-1 ring-emerald-300/20"><Activity className="h-3 w-3" />متصل بـ Supabase</span></div><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-300">تحكم مركزي في تجربة المستخدم والمحتوى والوصول والإرسال والتحليلات، مع الحفاظ على Webhook وجداول المنصة المصدرية.</p><p className="mt-2 text-[11px] text-slate-400">{lastSyncedAt ? `آخر مزامنة: ${new Date(lastSyncedAt).toLocaleString('ar-YE')}` : 'جارٍ مزامنة حالة التشغيل…'}</p></div></div><div className="flex flex-wrap gap-2"><button onClick={() => void load()} disabled={loading} className="inline-flex h-11 items-center gap-2 rounded-xl bg-white/10 px-4 text-xs font-bold text-white ring-1 ring-white/15 transition hover:bg-white/15 disabled:opacity-60">{loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}تحديث المركز</button><a href="https://t.me/Moieen2025Bot" target="_blank" rel="noreferrer" className="inline-flex h-11 items-center gap-2 rounded-xl bg-white px-4 text-xs font-black text-indigo-950 transition hover:bg-sky-50"><ExternalLink className="h-4 w-4" />فتح البوت</a></div></div>
      <div className="mt-7 grid grid-cols-2 gap-3 md:grid-cols-4"><div className="rounded-2xl bg-white/10 p-4 ring-1 ring-white/10"><p className="text-[11px] text-slate-400">إجمالي مستخدمي البوت</p><p className="mt-1 text-2xl font-black">{botStats?.totalSubscribers?.toLocaleString('ar-YE') ?? '—'}</p><p className="mt-1 text-[10px] text-slate-400">كل المسجلين في Supabase</p></div><div className="rounded-2xl bg-white/10 p-4 ring-1 ring-white/10"><p className="text-[11px] text-slate-400">المستخدمون النشطون</p><p className="mt-1 text-2xl font-black">{botStats?.activeUsers?.toLocaleString('ar-YE') ?? '—'}</p><p className="mt-1 text-[10px] text-slate-400">آخر {botStats?.activeUsersPeriodDays ?? 30} يومًا</p></div><div className="rounded-2xl bg-white/10 p-4 ring-1 ring-white/10"><p className="text-[11px] text-slate-400">تفاعلات 30 يومًا</p><p className="mt-1 text-2xl font-black">{usageAnalytics?.totalEvents?.toLocaleString('ar-YE') ?? '—'}</p></div><div className="rounded-2xl bg-white/10 p-4 ring-1 ring-white/10"><p className="text-[11px] text-slate-400">طلبات معلقة</p><p className="mt-1 text-2xl font-black">{subscriptionRequests.length.toLocaleString('ar-YE')}</p></div></div>
    </section>
    <nav className="sticky top-2 z-20 flex gap-2 overflow-x-auto rounded-2xl border border-slate-200/80 bg-white/90 p-2 shadow-lg shadow-slate-900/5 backdrop-blur" aria-label="أقسام مركز تشغيل البوت"><a href="#bot-access" className="whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold text-slate-600 transition hover:bg-indigo-50 hover:text-indigo-700"><ShieldCheck className="ml-1 inline h-3.5 w-3.5" />الوصول والإحالات</a><a href="#bot-content" className="whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold text-slate-600 transition hover:bg-indigo-50 hover:text-indigo-700"><LayoutList className="ml-1 inline h-3.5 w-3.5" />المحتوى والقوائم</a><a href="#bot-library" className="whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold text-slate-600 transition hover:bg-indigo-50 hover:text-indigo-700"><Database className="ml-1 inline h-3.5 w-3.5" />المكتبة</a><a href="#bot-messaging" className="whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold text-slate-600 transition hover:bg-indigo-50 hover:text-indigo-700"><Workflow className="ml-1 inline h-3.5 w-3.5" />الإرسال</a><a href="#bot-analytics" className="whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold text-slate-600 transition hover:bg-indigo-50 hover:text-indigo-700"><BarChart3 className="ml-1 inline h-3.5 w-3.5" />التحليلات</a></nav>
    <div id="bot-access"><AdminTelegramReferrals /></div>
    <section className="rounded-3xl border border-indigo-100 bg-indigo-50/50 p-5 shadow-sm"><div className="flex items-start gap-2"><Send className="mt-0.5 h-5 w-5 text-indigo-700" /><div><h2 className="font-black text-slate-800">جدولة بث جماعي</h2><p className="mt-1 text-xs leading-5 text-slate-600">اختر مسودة سابقة، ثم الموعد حسب توقيت جهازك. لا يتم الإرسال إلا بعد كتابة <bdi className="font-mono">SCHEDULE</bdi>، ويمكن إلغاء الموعد قبل التنفيذ. {botStats?.storageMode === 'supabase' ? 'الجدولة التلقائية غير مفعّلة حاليًا في تشغيل Supabase، لذا استخدم الإرسال الفوري المؤكد.' : ''}</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-4"><select value={schedulingBroadcastId ?? ''} onChange={event => setSchedulingBroadcastId(event.target.value ? Number(event.target.value) : null)} disabled={botStats?.storageMode === 'supabase'} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary"><option value="">اختر مسودة البث</option>{broadcasts.filter(item => item.status === 'draft' && !item.scheduledFor).map(item => <option key={item.id} value={item.id}>مسودة #{item.id} — {item.message?.slice(0, 36) || 'رسالة'}</option>)}</select><input type="datetime-local" value={scheduleFor} onChange={event => setScheduleFor(event.target.value)} disabled={botStats?.storageMode === 'supabase'} min={new Date(Date.now() + 60_000).toISOString().slice(0, 16)} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary" /><input value={scheduleConfirmation} onChange={event => setScheduleConfirmation(event.target.value)} disabled={botStats?.storageMode === 'supabase'} placeholder="اكتب SCHEDULE" dir="ltr" className="h-11 rounded-xl border border-indigo-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary" /><button onClick={() => schedulingBroadcastId && void scheduleBroadcast(schedulingBroadcastId)} disabled={botStats?.storageMode === 'supabase' || !schedulingBroadcastId || broadcastSaving} className="h-11 rounded-xl bg-indigo-700 px-4 text-xs font-bold text-white disabled:opacity-60">{botStats?.storageMode === 'supabase' ? 'الجدولة غير مفعّلة' : 'جدولة الإرسال'}</button></div>{broadcasts.filter(item => item.status === 'draft' && item.scheduledFor).length > 0 && <div className="mt-4 space-y-2">{broadcasts.filter(item => item.status === 'draft' && item.scheduledFor).map(item => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-indigo-100 bg-white p-3 text-sm"><span><b>مسودة #{item.id}</b> · مجدول: {new Date(item.scheduledFor!).toLocaleString('ar-YE')}</span><button onClick={() => void cancelBroadcast(item.id)} className="h-9 rounded-xl bg-rose-50 px-3 text-xs font-bold text-rose-700">إلغاء الموعد</button></div>)}</div>}</section>
    <section className="hidden rounded-3xl bg-gradient-to-l from-indigo-700 via-blue-700 to-sky-600 p-7 text-white shadow-xl"><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="flex gap-4"><div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-white/15"><Bot className="h-7 w-7" /></div><div><h1 className="text-2xl font-black">مركز إدارة بوت الناصر</h1><p className="mt-1 text-sm text-blue-100">اضبط ظهور الأقسام والأزرار والرسائل والروابط من مساحة إدارية واحدة.</p></div></div><a href="https://t.me/Moieen2025Bot" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 self-start rounded-xl bg-white px-4 py-2.5 text-sm font-bold text-blue-700"><ExternalLink className="h-4 w-4" />فتح البوت</a></div></section>

    <section id="bot-content" className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-start justify-between gap-4"><div><div className="flex items-center gap-2"><LayoutList className="h-5 w-5 text-primary" /><h2 className="font-black text-slate-800">الأقسام الأساسية</h2></div><p className="mt-1 text-xs leading-5 text-slate-500">يمكنك تعديل التسمية والترتيب والظهور. ولأقسام الاشتراك فقط، بدّل بنقرة واحدة بين الوصول المجاني ومنطق الاشتراك والإحالة الحالي؛ تبقى متطلبات القنوات وزيارة المنصة سارية.</p></div><span className="shrink-0 rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">{sections.filter(section => section.enabled).length} ظاهر</span></div>
      {loading ? <div className="flex justify-center py-12"><Loader2 className="h-7 w-7 animate-spin text-primary" /></div> : <div className="grid gap-3 md:grid-cols-2">{sections.map(section => <article key={section.sectionKey} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex items-center justify-between gap-3"><span className={`rounded-full px-2 py-0.5 text-[10px] font-black ${section.enabled ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-500'}`}>{section.enabled ? 'ظاهر للمستخدمين' : 'مخفي'}</span><label className="flex items-center gap-2 text-xs font-bold text-slate-600">إظهار<input type="checkbox" checked={section.enabled} onChange={event => updateSectionState(section.sectionKey, { enabled: event.target.checked })} className="h-4 w-4 accent-primary" /></label></div><label className="mt-3 block text-xs font-bold text-slate-600">اسم القسم<input value={section.displayLabel} onChange={event => updateSectionState(section.sectionKey, { displayLabel: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary" /></label><label className="mt-3 block text-xs font-bold text-slate-600">نمط الوصول<select value={section.accessMode === 'subscription' ? 'premium' : section.accessMode} onChange={event => updateSectionState(section.sectionKey, { accessMode: event.target.value as ManagedSection['accessMode'] })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary"><option value="free">متاح مجانًا</option><option value="premium">مدفوع</option><option value="referral">إحالة فقط</option><option value="hasad">زيارة حصاد اليوم</option></select><span className="mt-1 block text-[11px] font-normal leading-4 text-slate-500">{accessModeDescription(section.sectionKey)}</span></label><div className="mt-3 flex items-end gap-3"><label className="block flex-1 text-xs font-bold text-slate-600">الترتيب<input type="number" value={section.sortOrder} onChange={event => updateSectionState(section.sectionKey, { sortOrder: Number(event.target.value) })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-primary" /></label><button onClick={() => void saveSection(section)} disabled={savingSection === section.sectionKey} className="flex h-10 items-center gap-1.5 rounded-xl bg-slate-800 px-3 text-xs font-bold text-white hover:bg-slate-700 disabled:opacity-60">{savingSection === section.sectionKey ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}حفظ</button></div></article>)}</div>}
    </section>
    <section className="rounded-3xl border border-indigo-100 bg-indigo-50/40 p-5 shadow-sm"><div className="mb-4"><h2 className="font-black text-slate-800">تحكم سريع بوصول الأقسام</h2><p className="mt-1 text-xs leading-5 text-slate-600">اختر لكل زر أو قسم: مجاني، مدفوع، إحالة، أو توثيق زيارة حصاد اليوم، ثم اضغط حفظ. جميع الأزرار المولّدة داخل القسم ترث هذا الاختيار.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{sections.map(section => <article key={`access-${section.sectionKey}`} className="rounded-2xl border border-indigo-100 bg-white p-3"><p className="truncate text-sm font-bold text-slate-800">{section.displayLabel}</p><div className="mt-3 flex items-center gap-2"><select value={section.accessMode} onChange={event => updateSectionState(section.sectionKey, { accessMode: event.target.value as ManagedSection['accessMode'] })} className="h-10 min-w-0 flex-1 rounded-xl border border-indigo-200 bg-white px-2 text-xs text-slate-800 outline-none focus:border-indigo-500"><option value="free">متاح مجانًا</option><option value="premium">مدفوع</option><option value="referral">إحالة فقط</option><option value="hasad">زيارة حصاد اليوم</option></select><button onClick={() => void saveSection(section)} disabled={savingSection === section.sectionKey} className="flex h-10 shrink-0 items-center gap-1 rounded-xl bg-indigo-700 px-3 text-xs font-bold text-white disabled:opacity-60">{savingSection === section.sectionKey ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}حفظ</button></div></article>)}</div></section>

    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-start gap-2"><FileText className="mt-0.5 h-5 w-5 text-primary" /><div><h2 className="font-black text-slate-800">قوالب الرسائل التعريفية</h2><p className="mt-1 text-xs leading-5 text-slate-500">تُدار رسائل الترحيب و«عن المكتبة» والمساعدة فقط. تبقى رسائل الاشتراك والتحقق والدفع محمية وثابتة.</p></div></div>{loading ? <div className="flex justify-center py-10"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : <div className="grid gap-4 xl:grid-cols-3">{templates.map(template => <article key={template.messageKey} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><h3 className="font-bold text-slate-800">{template.title}</h3><textarea value={template.content} onChange={event => updateTemplateState(template.messageKey, event.target.value)} rows={8} className="mt-3 w-full resize-y rounded-xl border border-slate-200 bg-white p-3 text-sm leading-6 text-slate-700 outline-none focus:border-primary" /><button onClick={() => void saveTemplate(template)} disabled={savingTemplate === template.messageKey} className="mt-3 flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-slate-800 text-xs font-bold text-white hover:bg-slate-700 disabled:opacity-60">{savingTemplate === template.messageKey ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}حفظ القالب</button></article>)}</div>}</section>

    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><MessageSquareText className="h-5 w-5 text-primary" /><h2 className="font-black text-slate-800">طلبات اشتراك أهم القوانين</h2></div><p className="mt-1 text-xs leading-5 text-slate-500">تحقق من التحويل المحلي قبل الاعتماد. ترسل المنصة إشعارًا تلقائيًا للطالب بعد اتخاذ القرار.</p></div><span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-700">{subscriptionRequests.length} معلقة</span></div>{loading ? <div className="flex justify-center py-8"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : subscriptionRequests.length === 0 ? <p className="rounded-2xl bg-slate-50 p-5 text-center text-sm text-slate-500">لا توجد طلبات اشتراك معلقة حاليًا.</p> : <div className="grid gap-3 lg:grid-cols-2">{subscriptionRequests.map(requestItem => <article key={requestItem.id} className="rounded-2xl border border-amber-100 bg-amber-50/40 p-4"><div className="flex items-center justify-between"><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">طلب #{requestItem.id}</span><span className="text-[10px] text-slate-500">{new Date(requestItem.createdAt).toLocaleString('ar-YE')}</span></div><p className="mt-3 font-bold text-slate-800">{[requestItem.telegramFirstName, requestItem.telegramLastName].filter(Boolean).join(' ') || 'مستخدم تيليغرام'}</p><p className="mt-1 text-xs text-slate-600">{requestItem.telegramUsername ? `@${requestItem.telegramUsername}` : 'لا يوجد اسم مستخدم'} · المعرف: {requestItem.telegramUserId}</p><p className="mt-2 text-xs font-bold text-slate-600">طريقة الدفع: {requestItem.paymentMethod || 'لم تحدد'}</p><div className="mt-3 flex gap-2"><button onClick={() => void decideSubscription(requestItem, 'approve')} disabled={subscriptionActionId === requestItem.id} className="flex h-10 items-center gap-2 rounded-xl bg-emerald-600 px-4 text-xs font-bold text-white disabled:opacity-60">{subscriptionActionId === requestItem.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : null}اعتماد</button><button onClick={() => void decideSubscription(requestItem, 'reject')} disabled={subscriptionActionId === requestItem.id} className="h-10 rounded-xl bg-white px-4 text-xs font-bold text-rose-700 ring-1 ring-rose-100 disabled:opacity-60">رفض</button></div></article>)}</div>}</section>

    <section id="bot-analytics" className="rounded-3xl border border-emerald-100 bg-gradient-to-br from-emerald-50/70 to-white p-6 shadow-sm"><div className="mb-5 flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><div className="flex items-center gap-2"><BarChart3 className="h-5 w-5 text-emerald-700" /><h2 className="font-black text-slate-800">الزيارات الموثقة للمنصتين</h2></div><p className="mt-1 text-xs leading-5 text-slate-600">تصفية آمنة لزيارات منصة الناصر وحصاد اليوم. تُعرض الأسماء المتاحة للإدارة فقط مع وقت التوثيق.</p></div><select value={visitPeriod} onChange={event => void loadVisitAnalytics(event.target.value as VisitPeriod)} disabled={visitLoading} className="h-10 rounded-xl border border-emerald-200 bg-white px-3 text-sm font-bold text-slate-700 outline-none focus:border-emerald-500 disabled:opacity-60"><option value="day">اليوم</option><option value="week">آخر 7 أيام</option><option value="month">آخر 30 يومًا</option></select></div>{loading || visitLoading || !visitAnalytics ? <div className="flex justify-center py-10"><Loader2 className="h-6 w-6 animate-spin text-emerald-600" /></div> : <><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl border border-blue-100 bg-white p-4"><p className="text-xs font-bold text-slate-500">منصة الناصر القانونية</p><p className="mt-1 text-2xl font-black text-blue-700">{visitAnalytics.platformVisits.total}</p><p className="mt-1 text-xs text-slate-500">{visitAnalytics.platformVisits.uniqueUsers} مستخدمًا موثقًا</p></div><div className="rounded-2xl border border-amber-100 bg-white p-4"><p className="text-xs font-bold text-slate-500">حصاد اليوم</p><p className="mt-1 text-2xl font-black text-amber-700">{visitAnalytics.hasadVisits.total}</p><p className="mt-1 text-xs text-slate-500">{visitAnalytics.hasadVisits.uniqueUsers} مستخدمًا موثقًا</p></div></div><div className="mt-5 overflow-hidden rounded-2xl border border-slate-100 bg-white"><div className="border-b border-slate-100 px-4 py-3 text-sm font-black text-slate-800">المستخدمون الذين أتموا التوثيق خلال الفترة</div>{visitAnalytics.users.length === 0 ? <p className="p-5 text-center text-sm text-slate-500">لا توجد زيارات موثقة ضمن الفترة المختارة.</p> : <div className="divide-y divide-slate-100">{visitAnalytics.users.map(visitor => <article key={visitor.telegramUserId} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><p className="truncate font-bold text-slate-800">{visitorDisplayName(visitor)}</p><p className="mt-0.5 text-xs text-slate-500">{visitor.telegramUsername ? `@${visitor.telegramUsername} · ` : ''}معرّف: {visitor.telegramUserId}</p></div><div className="flex flex-wrap gap-2"><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ${visitor.platformVisitedAt ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-400'}`}>{visitor.platformVisitedAt ? `✓ منصة الناصر · ${new Date(visitor.platformVisitedAt).toLocaleString('ar-YE')}` : 'منصة الناصر غير موثقة'}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ${visitor.hasadVisitedAt ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-400'}`}>{visitor.hasadVisitedAt ? `✓ حصاد اليوم · ${new Date(visitor.hasadVisitedAt).toLocaleString('ar-YE')}` : 'حصاد اليوم غير موثق'}</span></div></article>)}</div>}</div></>}</section>

    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-start gap-2"><BarChart3 className="mt-0.5 h-5 w-5 text-primary" /><div><h2 className="font-black text-slate-800">تحليلات استخدام البوت</h2><p className="mt-1 text-xs leading-5 text-slate-500">مؤشرات مجمعة لآخر 30 يومًا؛ لا تعرض هذه الصفحة أسماء أو معرفات مستخدمي تيليغرام.</p></div></div>{loading || !usageAnalytics ? <div className="flex justify-center py-8"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : <><div className="grid grid-cols-2 gap-3 md:grid-cols-4"><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs text-slate-500">إجمالي التفاعلات</p><p className="mt-1 text-2xl font-black text-slate-800">{usageAnalytics.totalEvents}</p></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs text-slate-500">مستخدمون نشطون</p><p className="mt-1 text-2xl font-black text-slate-800">{usageAnalytics.uniqueUsers}</p></div>{usageAnalytics.eventTypes.slice(0, 2).map(item => <div key={item.eventType} className="rounded-2xl bg-slate-50 p-4"><p className="text-xs text-slate-500">{({ browse: 'تصفح', search: 'بحث', document_request: 'طلبات ملفات', support_request: 'دعم' } as Record<string, string>)[item.eventType] || item.eventType}</p><p className="mt-1 text-2xl font-black text-slate-800">{item.count}</p></div>)}</div><div className="mt-5 grid gap-4 lg:grid-cols-2"><div className="rounded-2xl border border-slate-100 p-4"><h3 className="font-bold text-slate-800">الأقسام الأكثر استخدامًا</h3><div className="mt-3 space-y-3">{usageAnalytics.topSections.length ? usageAnalytics.topSections.map(item => { const label = sections.find(section => section.sectionKey === item.sectionKey)?.displayLabel || item.sectionKey; const max = usageAnalytics.topSections[0]?.count || 1; return <div key={item.sectionKey}><div className="flex justify-between gap-3 text-xs"><span className="truncate text-slate-700">{label}</span><b>{item.count}</b></div><div className="mt-1 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.max(5, item.count / max * 100)}%` }} /></div></div>; }) : <p className="text-sm text-slate-500">ستظهر البيانات بعد تفاعل المستخدمين مع الأقسام.</p>}</div></div><div className="rounded-2xl border border-slate-100 p-4"><h3 className="font-bold text-slate-800">الملفات الأكثر طلبًا</h3><div className="mt-3 space-y-3">{usageAnalytics.topSources.length ? usageAnalytics.topSources.map(item => <div key={item.sourceId} className="flex items-center justify-between gap-3 text-sm"><span className="truncate text-slate-700">{item.title}</span><b className="shrink-0 text-primary">{item.count}</b></div>) : <p className="text-sm text-slate-500">ستظهر البيانات بعد طلب الملفات من البوت.</p>}</div></div></div></>}</section>

    <section id="bot-messaging" className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-start gap-2"><Send className="mt-0.5 h-5 w-5 text-primary" /><div><h2 className="font-black text-slate-800">بث جماعي للمشتركين</h2><p className="mt-1 text-xs leading-5 text-slate-500">ينشئ النظام مسودة ومعاينة أولًا، ولا يرسل أي رسالة إلا بعد كتابة <bdi className="font-mono">SEND</bdi> للتأكيد الصريح.</p></div></div><textarea value={broadcastMessage} onChange={event => setBroadcastMessage(event.target.value)} rows={4} maxLength={4000} placeholder="اكتب رسالة البث هنا…" className="w-full rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm leading-7 text-slate-800 outline-none focus:border-primary" /><div className="mt-3 flex items-center justify-between gap-3"><p className="text-xs text-slate-500">{broadcastMessage.length}/4000 حرف</p><button onClick={() => void createBroadcast()} disabled={broadcastSaving} className="flex h-10 items-center gap-2 rounded-xl bg-primary px-4 text-xs font-bold text-white disabled:opacity-60"><Send className="h-3.5 w-3.5" />إنشاء معاينة البث</button></div><div className="mt-5 space-y-3">{broadcasts.slice(0, 8).map(broadcast => <article key={broadcast.id} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2"><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">#{broadcast.id}</span><span className={`rounded-full px-2 py-1 text-[10px] font-black ${broadcast.status === 'sent' ? 'bg-emerald-100 text-emerald-700' : broadcast.status === 'draft' ? 'bg-amber-100 text-amber-700' : 'bg-slate-200 text-slate-600'}`}>{broadcast.status === 'sent' ? 'تم الإرسال' : broadcast.status === 'draft' ? 'مسودة' : broadcast.status === 'cancelled' ? 'ملغى' : 'جارٍ الإرسال'}</span></div><span className="text-xs text-slate-500">{broadcast.recipientCount} مستلمًا</span></div><p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-slate-700">{broadcast.message}</p>{broadcast.status === 'sent' && <p className="mt-2 text-xs text-slate-500">نجح: {broadcast.successCount} | تعذر: {broadcast.failureCount}</p>}{broadcast.status === 'draft' && <div className="mt-3 flex flex-wrap items-center gap-2">{confirmingBroadcastId === broadcast.id ? <><input value={broadcastConfirmation} onChange={event => setBroadcastConfirmation(event.target.value)} placeholder="اكتب SEND" dir="ltr" className="h-10 w-32 rounded-xl border border-amber-300 bg-white px-3 text-sm outline-none" /><button onClick={() => void confirmBroadcast(broadcast.id)} disabled={broadcastSaving} className="h-10 rounded-xl bg-rose-600 px-4 text-xs font-bold text-white disabled:opacity-60">تأكيد الإرسال</button><button onClick={() => { setConfirmingBroadcastId(null); setBroadcastConfirmation(''); }} className="h-10 rounded-xl bg-white px-3 text-xs font-bold text-slate-600">رجوع</button></> : <><button onClick={() => setConfirmingBroadcastId(broadcast.id)} className="h-10 rounded-xl bg-amber-500 px-4 text-xs font-bold text-white">إرسال بعد التأكيد</button><button onClick={() => void cancelBroadcast(broadcast.id)} className="h-10 rounded-xl bg-white px-4 text-xs font-bold text-rose-700">إلغاء المسودة</button></>}</div>}</article>)}</div></section>

    <section id="bot-library" className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex items-center gap-2"><FolderTree className="h-5 w-5 text-primary" /><h2 className="font-black text-slate-800">مجلدات فهرس البوت</h2></div><p className="mt-1 text-xs leading-5 text-slate-500">عدّل اسم المجلد وترتيبه. لا يسمح النظام بحذف أي مجلد يحتوي ملفاتًا أو مجلدات فرعية.</p></div><div className="flex w-full gap-2 lg:w-[420px]"><input value={folderQuery} onChange={event => setFolderQuery(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void loadFolders(); }} placeholder="ابحث باسم المجلد" className="h-10 min-w-0 flex-1 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-primary" /><button onClick={() => void loadFolders()} disabled={foldersLoading} className="flex h-10 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-white disabled:opacity-60">{foldersLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}بحث</button></div></div>{folders.length === 0 ? <p className="rounded-2xl border border-dashed border-slate-200 p-5 text-center text-sm text-slate-500">ابحث باسم المجلد لإدارته. لا تُحمّل المجلدات كاملة تلقائيًا.</p> : <div className="grid gap-3 lg:grid-cols-2">{folders.map(folder => <article key={folder.id} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex items-center justify-between"><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">{folder.collection}</span><span className="text-[10px] text-slate-400">#{folder.id}</span></div><div className="mt-3 grid grid-cols-[minmax(0,1fr)_100px] gap-3"><label className="text-xs font-bold text-slate-600">اسم المجلد<input value={folder.name} onChange={event => updateFolderState(folder.id, { name: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-bold text-slate-600">الترتيب<input type="number" value={folder.sortOrder} onChange={event => updateFolderState(folder.id, { sortOrder: Number(event.target.value) })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm" /></label></div><div className="mt-3 flex gap-2"><button onClick={() => void saveFolder(folder)} disabled={savingFolder === folder.id} className="flex h-10 items-center gap-2 rounded-xl bg-slate-800 px-4 text-xs font-bold text-white disabled:opacity-60">{savingFolder === folder.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}حفظ</button><button onClick={() => void removeFolder(folder)} className="flex h-10 items-center gap-2 rounded-xl bg-rose-50 px-4 text-xs font-bold text-rose-700 hover:bg-rose-100"><Trash2 className="h-3.5 w-3.5" />حذف فارغ</button></div></article>)}</div>}</section>

    <section id="bot-library-files" className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex items-center gap-2"><FileText className="h-5 w-5 text-primary" /><h2 className="font-black text-slate-800">فهرس ملفات البوت</h2></div><p className="mt-1 text-xs leading-5 text-slate-500">ارفع ملفًا محليًا إلى تخزين البوت، أو ابحث في الملفات المسجلة لتعديل العرض. الحذف يزيل السجل من البوت فقط ولا يمس المصدر الأصلي.</p></div><div className="flex w-full gap-2 lg:w-[420px]"><input value={sourceQuery} onChange={event => setSourceQuery(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void loadSources(); }} placeholder="ابحث باسم الملف أو وصفه" className="h-10 min-w-0 flex-1 rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-primary" /><button onClick={() => void loadSources()} disabled={sourceLoading} className="flex h-10 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-white disabled:opacity-60">{sourceLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}بحث</button></div></div><p className="mb-4 rounded-2xl border border-emerald-100 bg-emerald-50/60 p-4 text-xs leading-5 text-slate-600"><Database className="ml-1 inline h-4 w-4 text-emerald-700" /><b className="text-slate-800">مكتبة Drive المصدرية:</b> تُدار هنا بيانات العرض والترتيب والإخفاء فقط؛ لا تُخزّن ملفات PDF أو Word أو روابط Drive داخل Supabase، ولا تظهر روابط المصدر للمستخدم النهائي.</p><div className="mb-6 rounded-2xl border border-sky-100 bg-sky-50/70 p-4 text-xs leading-6 text-slate-600"><b className="text-slate-800">الرفع المحلي غير متاح في تشغيل Supabase.</b> الملفات تُقرأ من فهرس Drive المصدرية، ويمكنك هنا تعديل الاسم والوصف والترتيب والظهور فقط. لن يظهر زر رفع يؤدي إلى عملية غير مدعومة.</div><div className="hidden mb-6 rounded-2xl border border-emerald-100 bg-emerald-50/60 p-4"><div className="mb-3 flex items-center gap-2"><Database className="h-4 w-4 text-primary" /><h3 className="text-sm font-black text-slate-800">مكتبة Drive المصدرية</h3><span className="text-[10px] text-emerald-700">لا تُخزّن الملفات أو الروابط داخل Supabase</span></div><div className="grid gap-3 lg:grid-cols-4"><label className="text-xs font-bold text-slate-600">الملف<input type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.txt" onChange={event => { const file = event.target.files?.[0] ?? null; setUploadFile(file); if (file && !uploadDraft.title) setUploadDraft(current => ({ ...current, title: file.name.replace(/\.[^.]+$/, '') })); }} className="mt-1.5 block w-full text-xs" /></label><label className="text-xs font-bold text-slate-600">اسم العرض<input value={uploadDraft.title} onChange={event => setUploadDraft({ ...uploadDraft, title: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-bold text-slate-600">القسم<select value={uploadDraft.collection} onChange={event => setUploadDraft({ ...uploadDraft, collection: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="judicial">القواعد القضائية</option><option value="legislation">التشريعات اليمنية</option><option value="legal_forms">نماذج وصيغ قانونية</option><option value="featured_references">مراجع مميزة</option><option value="illustrated_legal_forms">نماذج مصورة</option><option value="all_yemeni_laws">جميع القوانين اليمنية</option></select></label><label className="text-xs font-bold text-slate-600">التصنيف<select value={uploadDraft.category} onChange={event => setUploadDraft({ ...uploadDraft, category: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="general">عام</option><option value="fiqh">فقه</option><option value="civil">مدني</option><option value="commercial">تجاري</option><option value="procedure">إجراءات</option></select></label></div><p className="text-xs leading-5 text-slate-600">تُدار هنا بيانات العرض والترتيب والإخفاء فقط، بينما يبقى الملف الأصلي في Drive ولا يظهر رابط Drive للمستخدم النهائي.</p><div className="hidden mt-3 grid gap-3 lg:grid-cols-[minmax(0,1fr)_110px_auto]"><label className="text-xs font-bold text-slate-600">وصف الملف <span className="text-rose-600">(مطلوب)</span><textarea value={uploadDraft.description} onChange={event => setUploadDraft({ ...uploadDraft, description: event.target.value })} rows={2} className="mt-1.5 w-full rounded-xl border border-slate-200 bg-white p-3 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-bold text-slate-600">الترتيب<input type="number" value={uploadDraft.sortOrder} onChange={event => setUploadDraft({ ...uploadDraft, sortOrder: Number(event.target.value) })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm" /></label><button onClick={() => void uploadSource()} disabled={uploading} className="self-end flex h-10 items-center gap-2 rounded-xl bg-primary px-4 text-xs font-bold text-white disabled:opacity-60">{uploading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Upload className="h-3.5 w-3.5" />}رفع وإضافة</button></div></div>{sources.length === 0 ? <div className="rounded-2xl border border-dashed border-slate-200 p-7 text-center text-sm text-slate-500">اكتب عبارة بحث ثم اضغط «بحث» لإدارة الملفات. لا تُحمّل القائمة كاملة تلقائيًا لحماية الأداء.</div> : <><p className="mb-3 text-xs text-slate-500">النتائج: {sourceTotal}</p><div className="space-y-3">{sources.map(source => <article key={source.id} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex items-center justify-between gap-3"><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">{source.collection}</span><label className="flex items-center gap-2 text-xs font-bold text-slate-600">مميز<input type="checkbox" checked={source.isFeatured} onChange={event => updateSourceState(source.id, { isFeatured: event.target.checked })} className="h-4 w-4 accent-primary" /></label></div><div className="mt-3 grid gap-3 lg:grid-cols-[minmax(0,1fr)_110px]"><label className="text-xs font-bold text-slate-600">اسم العرض<input value={source.title} onChange={event => updateSourceState(source.id, { title: event.target.value })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-primary" /></label><label className="text-xs font-bold text-slate-600">الترتيب<input type="number" value={source.sortOrder} onChange={event => updateSourceState(source.id, { sortOrder: Number(event.target.value) })} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-primary" /></label></div><label className="mt-3 block text-xs font-bold text-slate-600">الوصف<textarea value={source.description} onChange={event => updateSourceState(source.id, { description: event.target.value })} rows={3} className="mt-1.5 w-full rounded-xl border border-slate-200 bg-white p-3 text-sm leading-6 text-slate-700 outline-none focus:border-primary" /></label><div className="mt-3 flex gap-2"><button onClick={() => void saveSource(source)} disabled={savingSource === source.id} className="flex h-10 items-center gap-2 rounded-xl bg-slate-800 px-4 text-xs font-bold text-white hover:bg-slate-700 disabled:opacity-60">{savingSource === source.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}حفظ الملف</button><button onClick={() => void removeSource(source)} className="flex h-10 items-center gap-2 rounded-xl bg-rose-50 px-4 text-xs font-bold text-rose-700 hover:bg-rose-100"><Trash2 className="h-3.5 w-3.5" />حذف من البوت</button></div></article>)}</div></>}</section>

    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-center gap-2"><History className="h-5 w-5 text-primary" /><div><h2 className="font-black text-slate-800">سجل عمليات الإدارة</h2><p className="mt-1 text-xs text-slate-500">يسجل أحدث التعديلات على العناصر والأقسام، من دون إظهار أي رموز أو أسرار.</p></div></div>{loading ? <div className="flex justify-center py-7"><Loader2 className="h-5 w-5 animate-spin text-primary" /></div> : logs.length === 0 ? <p className="rounded-2xl bg-slate-50 p-4 text-center text-sm text-slate-500">لا توجد عمليات مسجلة في هذا المركز حتى الآن.</p> : <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{logs.slice(0, 12).map(log => <div key={log.id} className="rounded-2xl bg-slate-50 p-3"><div className="flex items-center justify-between gap-3"><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">{log.entityType === 'section' ? 'قسم' : 'زر'}</span><span className="text-[10px] text-slate-400">{new Date(log.createdAt).toLocaleString('ar-YE')}</span></div><p className="mt-2 text-sm font-bold text-slate-800">{log.action === 'create' ? 'إضافة' : log.action === 'delete' ? 'حذف' : 'تعديل'} {log.entityId ? `#${log.entityId}` : ''}</p></div>)}</div>}</section>

    <div className="grid gap-7 xl:grid-cols-[minmax(0,1fr)_380px]"><section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-black text-slate-800">الأزرار المخصصة</h2><p className="mt-1 text-xs text-slate-500">تضاف إلى القائمة الرئيسية للبوت. الأزرار الأساسية والأمنية تبقى محمية.</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700">{items.length} زر</span></div>{loading ? <div className="flex justify-center py-14"><Loader2 className="h-7 w-7 animate-spin text-primary" /></div> : items.length === 0 ? <div className="rounded-2xl border border-dashed border-slate-200 py-12 text-center"><Bot className="mx-auto h-9 w-9 text-slate-300" /><p className="mt-3 font-bold text-slate-600">لا توجد أزرار مخصصة بعد</p><p className="mt-1 text-xs text-slate-400">استخدم النموذج لإضافة رابط أو رسالة جديدة للمستخدمين.</p></div> : <div className="space-y-3">{items.map(item => <article key={item.id} className="flex items-center gap-4 rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white text-primary shadow-sm">{item.actionType === 'url' ? <ExternalLink className="h-4 w-4" /> : <MessageSquareText className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-bold text-slate-800">{item.label}</p><span className={`rounded-full px-2 py-0.5 text-[10px] font-black ${item.enabled ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-500'}`}>{item.enabled ? 'ظاهر' : 'مخفي'}</span><span className="rounded-full bg-blue-50 px-2 py-0.5 text-[10px] font-black text-blue-700">{actionLabel(item.actionType)}</span></div><p className="mt-1 truncate text-xs text-slate-500">{item.actionValue}</p></div><button onClick={() => { setEditingId(item.id); setDraft({ label: item.label, actionType: item.actionType, actionValue: item.actionValue, rowIndex: item.rowIndex, sortOrder: item.sortOrder, enabled: item.enabled }); }} className="rounded-xl p-2 text-slate-500 hover:bg-white hover:text-primary"><Pencil className="h-4 w-4" /></button><button onClick={() => void remove(item.id)} className="rounded-xl p-2 text-slate-500 hover:bg-rose-50 hover:text-rose-600"><Trash2 className="h-4 w-4" /></button></article>)}</div>}</section>
      <aside className="h-fit rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div className="mb-5 flex items-center justify-between"><h2 className="font-black text-slate-800">{title}</h2>{editingId && <button onClick={reset} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button>}</div><div className="space-y-4"><label className="block text-sm font-bold text-slate-700">اسم الزر<input value={draft.label} onChange={event => setDraft({ ...draft, label: event.target.value })} placeholder="مثال: المكتبة الجديدة" className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-primary" /></label><label className="block text-sm font-bold text-slate-700">نوع الإجراء<select value={draft.actionType} onChange={event => setDraft({ ...draft, actionType: event.target.value as Draft['actionType'] })} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-primary"><option value="url">فتح رابط</option><option value="message">عرض رسالة</option></select></label><label className="block text-sm font-bold text-slate-700">{draft.actionType === 'url' ? 'الرابط' : 'نص الرسالة'}{draft.actionType === 'url' ? <input value={draft.actionValue} onChange={event => setDraft({ ...draft, actionValue: event.target.value })} placeholder="https://..." dir="ltr" className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-primary" /> : <textarea value={draft.actionValue} onChange={event => setDraft({ ...draft, actionValue: event.target.value })} rows={5} placeholder="الرسالة التي يراها المستخدم" className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm outline-none focus:border-primary" />}</label><div className="grid grid-cols-2 gap-3"><label className="text-xs font-bold text-slate-600">ترتيب الصف<input type="number" value={draft.rowIndex} onChange={event => setDraft({ ...draft, rowIndex: Number(event.target.value) })} className="mt-2 h-10 w-full rounded-xl border border-slate-200 px-3" /></label><label className="text-xs font-bold text-slate-600">ترتيب الزر<input type="number" value={draft.sortOrder} onChange={event => setDraft({ ...draft, sortOrder: Number(event.target.value) })} className="mt-2 h-10 w-full rounded-xl border border-slate-200 px-3" /></label></div><label className="flex items-center justify-between rounded-xl bg-slate-50 p-3 text-sm font-bold text-slate-700">إظهار الزر للمستخدمين<input type="checkbox" checked={draft.enabled} onChange={event => setDraft({ ...draft, enabled: event.target.checked })} className="h-4 w-4 accent-primary" /></label><button disabled={saving} onClick={() => void save()} className="flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-primary text-sm font-bold text-white transition hover:bg-primary/90 disabled:opacity-60">{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}{editingId ? 'حفظ التعديل' : 'إضافة إلى البوت'}</button>{!editingId && <div className="flex items-center gap-2 text-xs text-slate-400"><Plus className="h-3.5 w-3.5" />تُسجل جميع عمليات الإضافة والتعديل والحذف للمراجعة.</div>}</div></aside></div>
    <section className="rounded-3xl border border-sky-100 bg-sky-50/40 p-5 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="font-black text-slate-800">محتوى الزر الجاري</h2><p className="mt-1 text-xs leading-5 text-slate-600">يمكن أن يفتح الزر رابطًا أو يعرض رسالة أو يرسل ملفًا محفوظًا في تخزين البوت.</p></div><label className="block w-full text-sm font-bold text-slate-700 sm:w-80">نوع المحتوى<select value={draft.actionType} onChange={event => setDraft({ ...draft, actionType: event.target.value as ManagedMenuItem['actionType'], actionValue: event.target.value === 'file' ? draft.actionValue : draft.actionValue })} className="mt-2 h-11 w-full rounded-xl border border-sky-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-sky-500"><option value="url">فتح رابط</option><option value="message">عرض رسالة</option><option value="file">إرسال ملف</option></select></label></div>{draft.actionType === 'file' && <div className="mt-3 rounded-xl bg-white p-3"><label className="block text-sm font-bold text-slate-700">اختر الملف <input type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.txt" onChange={event => { const file = event.target.files?.[0] ?? null; setMenuItemFile(file); if (file && !draft.label.trim()) setDraft({ ...draft, label: file.name.replace(/\.[^.]+$/, ''), actionType: 'file' }); }} className="mt-2 block w-full text-xs font-normal" /></label><p className="mt-2 text-xs text-slate-500">{menuItemFile ? `الملف المحدد: ${menuItemFile.name}` : editingId && draft.actionValue ? 'سيبقى الملف المحفوظ الحالي ما لم تختر ملفًا بديلًا.' : 'الملفات المدعومة: PDF وWord وExcel وTXT حتى 30 ميغابايت.'}</p></div>}</section>
    <section className="rounded-3xl border border-violet-100 bg-violet-50/40 p-5 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="font-black text-slate-800">وصول الزر الجاري</h2><p className="mt-1 text-xs leading-5 text-slate-600">اختر نمط الوصول عند الإضافة أو أثناء تعديل أي زر مخصص. لا تحتاج إلى إنشاء زر جديد لتغيير النمط.</p></div><label className="block w-full text-sm font-bold text-slate-700 sm:w-80">نمط الوصول<select value={activeDraftAccessMode} onChange={event => setDraft({ ...draft, accessMode: event.target.value as ManagedMenuItem['accessMode'] })} className="mt-2 h-11 w-full rounded-xl border border-violet-200 bg-white px-3 text-sm text-slate-800 outline-none focus:border-violet-500"><option value="free">متاح مجانًا</option><option value="premium">مدفوع</option><option value="referral">إحالة فقط</option><option value="hasad">زيارة حصاد اليوم</option></select></label></div>{(activeDraftAccessMode === 'premium' || activeDraftAccessMode === 'referral') && <p className="mt-3 rounded-xl bg-white p-3 text-xs leading-5 text-slate-600">{activeDraftAccessMode === 'referral' ? 'سيُفتح هذا الزر بعد اكتمال الإحالات المؤهلة.' : 'سيستخدم هذا الزر تدفق الدفع وإثبات الإيداع، مع بقاء الإحالة كخيار وصول مجاني حسب إعدادات البوت.'}</p>}</section>
    <section className="rounded-3xl border border-violet-100 bg-violet-50/40 p-5 shadow-sm"><div className="mb-4"><h2 className="font-black text-slate-800">وصول الأزرار المخصصة</h2><p className="mt-1 text-xs leading-5 text-slate-600">يظهر كل زر أنشأته هنا مع تحكم مباشر في نمط وصوله، من دون فتح نموذج التعديل.</p></div>{items.length === 0 ? <p className="rounded-xl bg-white p-4 text-center text-sm text-slate-500">لا توجد أزرار مخصصة بعد.</p> : <div className="grid gap-3 md:grid-cols-2">{items.map(item => <article key={`item-access-${item.id}`} className="rounded-2xl border border-violet-100 bg-white p-3"><div className="flex items-center justify-between gap-2"><p className="min-w-0 truncate text-sm font-bold text-slate-800">{item.label}</p><span className="shrink-0 rounded-full bg-violet-100 px-2 py-0.5 text-[10px] font-black text-violet-700">{accessModeLabel(item.accessMode)}</span></div><div className="mt-3 flex items-center gap-2"><select value={item.accessMode} onChange={event => void updateMenuItemAccessMode(item, event.target.value as ManagedMenuItem['accessMode'])} disabled={savingMenuItemAccessId === item.id} className="h-10 min-w-0 flex-1 rounded-xl border border-violet-200 bg-white px-2 text-xs text-slate-800 outline-none focus:border-violet-500 disabled:opacity-60"><option value="free">متاح مجانًا</option><option value="premium">مدفوع</option><option value="referral">إحالة فقط</option><option value="hasad">زيارة حصاد اليوم</option></select>{savingMenuItemAccessId === item.id && <Loader2 className="h-4 w-4 shrink-0 animate-spin text-violet-700" />}</div></article>)}</div>}</section>
  </div></AdminLayout>;
}
